// Имена компонентов Jinx UI взяты по общепринятому соглашению — сверь с версией пакета.
import { useEffect, useState } from 'react';
import { Button, Stack, TextField, Toast } from '@jinx-ui/react';

export default function NewsletterSubscribeForm() {
  const [email, setEmail] = useState('');
  const [isToastOpen, setIsToastOpen] = useState(false);

  useEffect(() => {
    if (!isToastOpen) return;
    const timeoutId = window.setTimeout(() => setIsToastOpen(false), 4000);
    return () => window.clearTimeout(timeoutId);
  }, [isToastOpen]);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setEmail('');
    setIsToastOpen(true);
  };

  return (
    <>
      <form onSubmit={handleSubmit} noValidate={false}>
        <Stack direction="row" gap="var(--jx-space-3)" align="end">
          <TextField
            type="email"
            name="email"
            label="Почта"
            placeholder="you@example.com"
            value={email}
            required
            onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
              setEmail(event.target.value)
            }
          />
          <Button type="submit" variant="primary" disabled={email.trim() === ''}>
            Подписаться
          </Button>
        </Stack>
      </form>

      {isToastOpen && (
        <Toast
          open
          status="success"
          title="Готово"
          placement="bottom-right"
          onClose={() => setIsToastOpen(false)}
        >
          Письмо отправлено — проверьте почту.
        </Toast>
      )}
    </>
  );
}

